#!/usr/bin/env node
/** Embed config/index.html into src/pkjs/settings/generated.js for offline Rebble config. */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const htmlPath = path.join(root, 'config', 'index.html');
const outDir = path.join(root, 'src', 'pkjs', 'settings');
const outPath = path.join(outDir, 'generated.js');

const html = fs.readFileSync(htmlPath, 'utf8');
const encoded = encodeURIComponent(html);
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(
  outPath,
  '/* auto-generated by scripts/generate-remote-config.js — do not edit */\n' +
    'module.exports = function getSettings() {\n' +
    '  return ' +
    JSON.stringify(encoded) +
    ';\n};\n'
);
console.log('Wrote', outPath, 'encoded length', encoded.length);
